`resetall
`timescale 1ns / 1ps

  module `IP_MODULE_NAME(cal_controller) #( 
	parameter [1:0] DDR_TYPE                = 2'b00,
	parameter 	I2C_CMD_BYTE_WIDTH 	= 8,
	parameter [7:0] I2C_TRX_BYTE 		= 8'h5,
	parameter	ROM_DATA_DEPTH0		= 16,
	parameter	ROM_DATA_DEPTH1		= 16,
	parameter	ROM_DATA_DEPTH2		= 16,
	parameter	ROM_DATA_DEPTH3		= 16,
	parameter	ROM_INIT_FILE0		= "rom0.hex",
	parameter	ROM_INIT_FILE1		= "rom1.hex",
	parameter	ROM_INIT_FILE2		= "rom2.hex",
	parameter	ROM_INIT_FILE3		= "rom3.hex"
	
  )(
   	//inputs
   	input 				clk,            //system Clock 
   	input 				rst_n,          //active Low Reset 
   	input 				restart,        //restart the Calibration
   	input 				enable_cal,     //enable the DDR calibration
	input [1:0]			cal_type,	//DDR type[0]
							//1'b0 - LPDDR3 / LPDDR2
							//1'b1 - DDR3
							//DDR type[1]
							//1'b0 - hard_cal
							//1'b1 - soft_cal
   	input [3:0] 			cal_mode,    	//DDR Calibration Mode
   	                         			//bit 0 - Gate Leveling
   	                         			//bit 1 - Write Leveling
   	                         			//bit 2 - Read Leveling
   	                         			//bit 3 - CA Leveling
	input [2:0]			cal_slice,
   	//outputs
   	output reg 			cal_done,       //calibration Done Flag
	output reg [6:0]		cal_status_reg,
	output[7:0]			cal_status_reg2,
   	output reg 			wr_rd_pass_reg, //write and read pass 
   	////////////////////
   	//I2c Interface
   	////////////////////
   	//inputs 
   	input 				i2c_busy,       //i2c Master Controller Busy
   	input [31:0] 			i2c_read_data,  //i2c read data (32 bits) 
   	//outputs
   	output [31:0] 			i2c_write_data, //i2c write datta (32 bits) 
   	output [I2C_CMD_BYTE_WIDTH-1:0] command_byte,
   	output [7:0] 			num_bytes,  	//Number of bytes to be sent. 
   	output reg			i2c_read,       //i2c read ctl 
   	output reg			i2c_write,      //i2c write ctl 
   	output 				i2c_soft_rst    //soft Reset. 
   );

//Parameters

   //ROM Settings 
   localparam ROM_DATA_WIDTH = 108; 	//{CONTROL BIT[11:0], MASK[31:0], DATA[31:0], ADDR[31:0]} 
					//CONTROL BIT
					//[3:0] Number of TRX
					//[4]	special rmw for data
					//[5]	special rmw for addr
					//[6]   Save i2c_read_data to register
					//[7]	cmd # overflow
					//[8]	rmw
					//[9]   read polling
					//[10]  read
					//[11]  write
   localparam ROM_OUTPUT_REG = 0;   
   //Control Bit Location 
   localparam WR_BIT         	= ROM_DATA_WIDTH-1; 
   localparam RD_BIT         	= ROM_DATA_WIDTH-2; 
   localparam RD_POLL_BIT    	= ROM_DATA_WIDTH-3; 
   localparam RMW_BIT        	= ROM_DATA_WIDTH-4; 
   localparam ROM_OVERFLOW     	= ROM_DATA_WIDTH-5;
   localparam SAVE_RD_BIT    	= ROM_DATA_WIDTH-6;
   localparam RMW_ADDR_BIT   	= ROM_DATA_WIDTH-7;
   localparam RMW_DATA_BIT   	= ROM_DATA_WIDTH-8;
   localparam [15:0] I2C_DELAY 	= 16'h01FF;

//Internal Signals 
   //Calibrator fsm
   reg 		sel_reset;
   wire 	rom_fsm_start;
   reg		rom_fsm_next_cmd;
   reg		rom_fsm_done;
   wire		rom_overflow;
   reg [6:0] 	rom_cmd_cnt;
   wire[6:0]	rom_cmd_end;
   wire 	rom_cmd_cnt_load;
   wire 	rom_cmd_cnt_empty;
   wire		rom_cmd_data_ready;
   reg [31:0]	i2c_read_data_register;
   reg [3:0]    cal_next_st,
		cal_current_st;
   reg [7:0]	cal_loop_1_cnt,
		cal_loop_2_cnt;
   wire		cal_loop_1_reset,
		cal_loop_2_reset;
   wire 	cal_loop_1_active,
		cal_check_1_active,
		cal_loop_2_active,
		cal_loop_3_active,
		cal_base_active,
		cal_base_end_active;
  reg        	cal_loop_1_active_reg   = 1'b0,
		cal_loop_2_active_reg   = 1'b0,
		cal_loop_3_active_reg   = 1'b0,
		cal_base_end_active_reg = 1'b0;
   wire		cal_gate_leveling;
   reg [27:0] 	i2c_delay_cnt;
   reg	  	i2c_delay_assert;
   reg [31:0]	target_leveling;
   reg		ca_leveling_track;
   reg 		cal_leveling_latch;    
   //i2c fsm
   reg		rmw_active;
   reg 	  	rd_en;
   wire   	rd_en_t;
   wire	 	rd_en_dummy;
   wire [3:0] 	rom_rd_full;
   reg  [3:0]  	delay_cnt;
   reg 	      	en_delay_cnt;
   reg 	      	wr_rd_pass;
   reg 	      	i2c_wr;
   reg 	      	i2c_rd;
   reg 	      	addr_wr;
   reg 	      	addr_wr_reg;
   wire [31:0] 	masked_rom_data_out;
   wire [31:0] 	masked_i2c_read_data;
   reg  [31:0] 	i2c_write_data_latch;
   reg  [3:0]   rom_sel_reg;
   reg  [3:0]   rom_sel;  
   wire 	cmd_wr;
   wire 	cmd_rd;
   wire		cmd_rmw_addr;
   wire		cmd_rmw_data;
   wire 	cmd_polling_rd;
   wire 	md_wr_rd;
   wire [ROM_DATA_WIDTH-1:0]   
			rom_data_out;
   wire [31:0]  mask_ctl;
   wire [31:0]  data_ctl;
   wire [31:0]  rmw_wdata;
   //soft-cal
   reg  [8:0]	soft_lvl_cnt;
   wire [8:0]   soft_lvl_number;
   wire [8:0]	soft_wr_number;
   wire [8:0]	soft_rd_number;
   reg  [2:0]	soft_slice_cnt;
   reg  [31:0]	soft_slice_addr;
   reg  [31:0]	soft_slice_data;
   wire		main_sel_reset;
   wire [1:0]	rom_sel_reset;
   wire		soft_delay_assert;
   reg  [15:0]	soft_delay;
   reg		cal_gate_leveling_last;
   wire		cal_gate_save;
   wire		cal_gate_AND_zeroes;
   wire		cal_gate_AND_match;
   reg		soft_cal_frst_reg;
   wire		soft_cal_frst;
   reg 		rd_page_sw;
   reg  [8:0] 	rd_first_value;
   wire 	rd_first_delay;
   reg  [1:0] 	rd_first_delay_capture;
   reg  [31:0] 	rd_address_mask;
   reg  [31:0] 	rd_mask;
   wire		rd_page_rst;
   reg		rd_ready;	
   wire		rd_ori_save;
   reg [63:0]	rd_ori_value;

////////////////////////////////////////////////////
//CAL FSM
////////////////////////////////////////////////////
    localparam [3:0] 
		CAL_IDLE		= 4'b0000,
		CAL_START               = 4'b0001,
		CAL_FIRST_READ		= 4'b0010,
		CAL_LOAD_CNT		= 4'b0011,
		CAL_EXE_BASE		= 4'b0100,
		CAL_CHECK_LOOP_1	= 4'b0101,
		CAL_EXE_LOOP_1		= 4'b0110,
		CAL_EXE_LOOP_2		= 4'b0111,
		CAL_PRE_CHECK_LOOP_2	= 4'b1000,
		CAL_CHECK_LOOP_2	= 4'b1001,
		CAL_SOFT_CHECK_LOOP_2	= 4'b1010,
		CAL_EXE_LOOP_3		= 4'b1011,
		CAL_EXE_BASE_END	= 4'b1100,
		CAL_SOFT_SWITCH_PAGE	= 4'b1101,
		CAL_SOFT_SLICE_RESTART	= 4'b1110,
		CAL_DONE		= 4'b1111;


////////////////////////////////////////////////////
//I2C FSM
////////////////////////////////////////////////////
   //== State enumeration
   localparam [4:0] // synopsys enum state_info
		ST_IDLE			= 5'b00000,
		ST_START                = 5'b00001,
		ST_CAL_MODE		= 5'b00010,
		ST_RD0_ROM		= 5'b00011,
		ST_RD1_ROM		= 5'b00100,
		ST_RD2_ROM		= 5'b00101,
		ST_RD3_ROM		= 5'b00110,
		ST_G_WR			= 5'b00111,
		ST_G_WR_CHK_BUSY	= 5'b01000,
		ST_G_WR_CHK_DONE	= 5'b01001,
		ST_G_RD			= 5'b01010,
		ST_G_RD_CHK_BUSY	= 5'b01011,
		ST_G_RD_CHK_DONE	= 5'b01100,
		ST_G_RD_POLL		= 5'b01101,
		ST_G_RD_POLL_CHK_BUSY	= 5'b01110,
		ST_G_RD_POLL_CHK_DONE	= 5'b01111,
		ST_G_RD_POLL_COMPARE    = 5'b10000,
		ST_G_WR1                = 5'b10001,
		ST_G_WR1_CHK_BUSY       = 5'b10010,
		ST_G_WR1_CHK_DONE       = 5'b10011,
		ST_G_RD1                = 5'b10100,
		ST_G_RD1_CHK_BUSY       = 5'b10101,
		ST_G_RD1_CHK_DONE       = 5'b10110,
   		ST_G_RMW                = 5'b10111,
                ST_G_RMW_CHK_BUSY       = 5'b11000,
                ST_G_RMW_CHK_DONE       = 5'b11001,
                ST_G_RMW_W              = 5'b11010,
                ST_G_RMW_W_CHK_BUSY     = 5'b11011,
                ST_G_RMW_W_CHK_DONE     = 5'b11100,
		ST_DONE                 = 5'b11111;
   
   //== State variables
   reg [4:0]  /* synopsys enum state_info */
	      current_st;		/* synopsys state_vector current_st */
   reg [4:0]  /* synopsys enum state_info */
	      next_st;

   assign cmd_wr 	 = rom_data_out[WR_BIT];
   assign cmd_rd 	 = rom_data_out[RD_BIT];
   assign cmd_polling_rd = rom_data_out[RD_POLL_BIT];
   assign cmd_wr_rd 	 = 1'b0;
   assign cmd_save_rd 	 = rom_data_out[SAVE_RD_BIT];
   assign cmd_rmw 	 = rom_data_out[RMW_BIT];
   assign cmd_rmw_addr 	 = rom_data_out[RMW_ADDR_BIT];
   assign cmd_rmw_data 	 = rom_data_out[RMW_DATA_BIT];
   assign rom_overflow 	 = rom_data_out[ROM_OVERFLOW];

   //32-bits data masking bits 
   assign masked_rom_data_out[31:0] = rom_data_out[ (2*32-1) : ((2-1)*32)] 	//Expected Data (2nd) 
					& rom_data_out[(3*32-1): ((3-1)*32)];	//Mask Bit (3rd) 
   
   assign masked_i2c_read_data[31:0] = i2c_read_data[31:0] & mask_ctl;
					//& rom_data_out[ (3*32-1): ((3-1)*32)];

   //assign i2c_write_data = (addr_wr_reg) ? rom_data_out[ (2*32-1) : ((2-1)*32)] : 
   //			rom_data_out[ (1*32-1) : ((1-1)*32)] ;
   assign i2c_write_data = (addr_wr_reg) ? ( (rmw_active) ? rmw_wdata : data_ctl )
                                         : cmd_rmw_addr ? ((rom_data_out[ (1*32-1) : ((1-1)*32)] | soft_slice_addr) & rd_address_mask): rom_data_out[ (1*32-1) : ((1-1)*32)] ;
   assign rmw_wdata = cmd_rmw_data ? masked_i2c_read_data | ((data_ctl | soft_slice_data) & ~mask_ctl) :  masked_i2c_read_data | (data_ctl & ~mask_ctl);
  
   assign mask_ctl = cmd_rmw_data? (rom_data_out[(3*32-1): ((3-1)*32)] ^ rd_mask) : rom_data_out[(3*32-1): ((3-1)*32)];
   assign data_ctl = rom_data_out[(2*32-1): ((2-1)*32)];

   ///////////////////////////////////////////
   //Command Byte Decoding for I2C2APB
   //addr type - 0x01 when addr_wr_reg = 0
   //data type - 0x00 when addr_wr_reg = 1
   ///////////////////////////////////////////
   assign  command_byte = (~addr_wr_reg) ? 8'h01 : 8'h00;

//////////////////
//Calibrator Logic
//////////////////

assign rom_cmd_cnt_load 	= (cal_current_st == CAL_LOAD_CNT);
assign rom_fsm_start		= (cal_current_st == CAL_START); 
assign rom_cmd_end 		= rom_data_out[ROM_DATA_WIDTH-9:ROM_DATA_WIDTH-12];
assign rom_cmd_data_ready 	= delay_cnt[2];
assign cal_gate_AND_zeroes	= ((i2c_read_data_register & target_leveling) == 0);
assign cal_gate_AND_match	= ((i2c_read_data_register & target_leveling) == target_leveling);
assign cal_gate_leveling	= rd_page_sw ? 
				  (cal_type[0] && cal_mode[2]? cal_gate_AND_match  : cal_gate_AND_zeroes) :
				  (cal_type[0] && cal_mode[2]? cal_gate_AND_zeroes : cal_gate_AND_match) ;

assign cal_loop_1_reset		= cal_mode[3]? 1'b0 : (cal_current_st == CAL_EXE_LOOP_1);
assign cal_loop_2_reset		= (cal_current_st == CAL_EXE_LOOP_3);
assign main_sel_reset		= (cal_current_st == CAL_SOFT_SLICE_RESTART) | soft_cal_frst;


assign cal_status_reg2 = i2c_read_data_register[15:8];

always@(posedge clk)
begin
	if(cal_type[1]) begin 	//soft
		case(cal_mode)
		4'b0001: target_leveling <= 32'h0001_0000;
		4'b0010: target_leveling <= 32'h0000_0010;
		4'b0100: target_leveling <= rd_page_sw ? 32'h0000_5500:32'h0000_aa00;
		default: target_leveling <= 32'hFFFF_FFFF;
		endcase
	end
	else begin		//phy
		case(cal_mode)
		4'b0001: target_leveling <= 32'h0000_0004;
		4'b0100: target_leveling <= 32'h0000_0002;
		4'b1000: target_leveling <= 32'h0000_0008;
		default: target_leveling <= 32'hFFFF_FFFF;
		endcase
	end
end


always @(posedge clk)
begin
	if(~rst_n || restart || main_sel_reset)
		rom_cmd_cnt <= 7'h0;
	else begin
		if(rom_cmd_cnt_load)
			rom_cmd_cnt <= {2'h0, rom_overflow, rom_cmd_end[3:0]} - 1'b1;
		else if (rom_fsm_next_cmd && !rom_cmd_cnt_empty)
			rom_cmd_cnt <= rom_cmd_cnt - 1'b1;
		else
			rom_cmd_cnt <= rom_cmd_cnt;
	end
end

assign rom_cmd_cnt_empty = (rom_cmd_cnt == 7'h0);

always @(posedge clk)
begin	
	if(~rst_n || restart || main_sel_reset)
		cal_loop_1_cnt <= 8'h0;
	else begin
		if (cal_loop_1_reset)
			cal_loop_1_cnt <= 8'h0;
		else if(cal_check_1_active)
			cal_loop_1_cnt <= cal_loop_1_cnt + 1'b1;	
		else
			cal_loop_1_cnt <= cal_loop_1_cnt;
	end
end 

assign cal_check_1_active = (cal_current_st == CAL_CHECK_LOOP_1);
assign cal_loop_1_active = (cal_current_st == CAL_EXE_LOOP_1);

always @(posedge clk)
begin
	if(~rst_n)
		cal_loop_1_active_reg <= 1'b0;
	else begin
		if (rom_cmd_cnt_empty && rom_fsm_done)
			cal_loop_1_active_reg <= 1'b0;
		else if(cal_loop_1_active)
			cal_loop_1_active_reg <= 1'b1;
		else
			cal_loop_1_active_reg <= cal_loop_1_active_reg;
	end
end

always @(posedge clk)
begin	
	if(~rst_n || restart || main_sel_reset || rd_page_rst)
		cal_loop_2_cnt <= 8'h0;
	else begin
		if (cal_loop_2_reset)
			cal_loop_2_cnt <= 8'h0;
		else if(cal_loop_2_active && rom_fsm_done)
			cal_loop_2_cnt <= cal_loop_2_cnt + 1'b1;
		else
			cal_loop_2_cnt <= cal_loop_2_cnt;
	end
end 

assign cal_loop_2_active = (cal_current_st == CAL_EXE_LOOP_2);

always @(posedge clk)
begin
	if (~rst_n)
		cal_loop_2_active_reg <= 1'b0;
	else begin
		if (rom_cmd_cnt_empty && rom_fsm_done)
			cal_loop_2_active_reg <= 1'b0;
		else if(cal_loop_2_active)
			cal_loop_2_active_reg <= 1'b1;
		else
			cal_loop_2_active_reg <= cal_loop_2_active_reg;
	end
end

assign cal_loop_3_active = (cal_current_st == CAL_EXE_LOOP_3);

always @(posedge clk)
begin
	if (~rst_n)
		cal_loop_3_active_reg <= 1'b0;
	else begin
		if (rom_cmd_cnt_empty && rom_fsm_done)
	  		cal_loop_3_active_reg <= 1'b0;
		else if(cal_loop_3_active)
			cal_loop_3_active_reg <= 1'b1;
		else
			cal_loop_3_active_reg <= cal_loop_3_active_reg;
	end
end

assign cal_base_active	   = (cal_current_st == CAL_EXE_BASE);
assign cal_base_end_active = (cal_current_st == CAL_EXE_BASE_END);

always @(posedge clk)
begin
	if (~rst_n)
		cal_base_end_active_reg <= 1'b0;
	else begin
		if (rom_cmd_cnt_empty && rom_fsm_done)
			cal_base_end_active_reg <= 1'b0;
		else if(cal_base_end_active)
			cal_base_end_active_reg <= 1'b1;
		else
			cal_base_end_active_reg <= cal_base_end_active_reg;
	end
end

always @(posedge clk)
begin
	if(~rst_n || rd_page_rst || main_sel_reset || restart)
		i2c_read_data_register <= 32'h0;
	else
	begin
		if(cmd_save_rd && rom_fsm_done)
			i2c_read_data_register <= i2c_read_data;
		else
			i2c_read_data_register <= i2c_read_data_register;
	end
end

always @(posedge clk)
begin
	if (cal_mode[2] && cal_base_active && cmd_save_rd)
		rd_ready <= i2c_busy;
	else
		rd_ready <= 1'b0;
end

assign rd_ori_save = ~i2c_busy & rd_ready;


always @(posedge clk)
begin
	if(rd_ori_save)
		rd_ori_value <= {rd_ori_value[31:0], (i2c_read_data & ~mask_ctl)};
	else
		rd_ori_value <= rd_ori_value;
end


always @(posedge clk)
begin
	if(~rst_n)
		cal_status_reg <= 'h0;
	else begin
	cal_status_reg <= {cal_gate_leveling_last, cal_leveling_latch, cal_base_end_active_reg, cal_loop_3_active_reg, cal_loop_2_active_reg, cal_loop_1_active_reg, cal_base_active };
	end
end

always @(posedge clk)
begin
	if(~rst_n)
		cal_leveling_latch <= 'h0;
	else begin
		if (cal_gate_leveling)
			cal_leveling_latch <= 1'b1;
		else if (!cal_gate_leveling)
			cal_leveling_latch <= 1'b0;
		else
			cal_leveling_latch <= cal_leveling_latch;
	end
end

assign cal_base_active = (cal_current_st == CAL_EXE_BASE);

always @(posedge clk)
begin
	if(~rst_n)
		ca_leveling_track <= 1'b0;
	else
	begin
		if(cal_done)
			ca_leveling_track <= 1'b0;
		else if(rom_fsm_done && cal_loop_1_active)
			ca_leveling_track <= 1'b1;
		else
			ca_leveling_track <= ca_leveling_track;
	end
end

//////////////////
//Soft Leveling
//////////////////
wire delay_fine_max;
wire delay_course_reg;
wire delay_course_max;
reg  [3:0] delay_course_value;
wire [3:0] soft_course_number;
wire	   soft_lvl_max;

assign delay_fine_max   = cal_mode[0]? soft_lvl_cnt[7] : 'b0;
assign delay_course_reg = cal_mode[0]? (rom_data_out[31:0] == 'h02) : 'b0;
assign soft_lvl_max = (soft_lvl_cnt == 'hF8);

always @(posedge clk)
begin
	if(~rst_n || restart || main_sel_reset || rd_page_rst || delay_fine_max)
		soft_lvl_cnt <= 'h0;
	else 
	begin
		if(cal_type[1]) begin
			if(cal_gate_save )
				soft_lvl_cnt <= soft_lvl_cnt + 'h8;
			else
				soft_lvl_cnt <= soft_lvl_cnt;
		end
		else 
			soft_lvl_cnt <= 'h0;
	end
end

assign delay_course_max = (delay_course_value == 'h06);

always @(posedge clk)
begin
	if(~rst_n || restart || main_sel_reset || rd_page_rst || delay_course_max)
		//course delay start value
		delay_course_value <= 'h1;
	else begin
		if(delay_fine_max)
			delay_course_value <= delay_course_value + 1'b1;
		else
			delay_course_value <= delay_course_value;
	end
end

always @(posedge clk)
begin
	if(~rst_n || restart)
		soft_slice_cnt <= 'h0;
	else
	begin
		if(cal_type[1]) begin
			case(cal_mode)
			4'b0100:
			begin
			if(cal_done)
				soft_slice_cnt <= 'h0;
			else if(cal_base_end_active && rom_fsm_done && rd_page_sw)
				soft_slice_cnt <= soft_slice_cnt + 1'b1;
			else
				soft_slice_cnt <= soft_slice_cnt;
			end
			default:
			begin
			if(cal_done)
				soft_slice_cnt <= 'h0;
			else if(cal_base_end_active && rom_fsm_done)
				soft_slice_cnt <= soft_slice_cnt + 1'b1;
			else
				soft_slice_cnt <= soft_slice_cnt;
			end
			endcase
		end
		else
			soft_slice_cnt <= 'h0;
	end
end


always @(posedge clk)
begin
	if(cal_type[1]) begin
		soft_slice_addr <= {26'h0,soft_slice_cnt,4'h0};
	end
	else begin
		soft_slice_addr <= 'h0;
	end
end

assign soft_lvl_number    = (soft_lvl_cnt > 64)? soft_lvl_cnt - 64 : 'h0;
assign soft_course_number = (soft_lvl_cnt < 64)? (delay_course_value == 'h0)? 'h0 : delay_course_value - 1 : delay_course_value;
assign soft_wr_number = soft_lvl_cnt + 'h40;
assign soft_rd_number = soft_lvl_cnt + rd_first_value;

always @(posedge clk)
begin
	case(cal_mode)
	4'b0001:
	begin
		if(cal_type[1]) begin
			if(cal_base_end_active)
				soft_slice_data <= delay_course_reg ? {2'h0, soft_course_number[0], 26'h0, soft_course_number[3:1]} : {soft_lvl_number[7:0], 24'h0};
			else
				soft_slice_data <= delay_course_reg ? {2'h0, delay_course_value[0], 26'h0, delay_course_value[3:1]} : {soft_lvl_cnt, 24'h0};
		end
		else begin
			soft_slice_data <= 'h0;
		end
	end
	4'b0010:
	begin
		soft_slice_data <= {8'h0, soft_lvl_cnt[7:0], soft_wr_number[7:0] , 8'h0};   
	end
	4'b0100:
	begin
		if(cal_loop_2_active && !rd_page_sw)
			soft_slice_data <= {24'h0, soft_lvl_cnt[7:0]};
		else if (cal_base_end_active && !rd_page_sw)
			soft_slice_data <= soft_lvl_max? {24'h0, rd_ori_value[39:32]}        : {24'h0, soft_rd_number[8:1]};
		else if (cal_base_end_active && rd_page_sw)
			soft_slice_data <= soft_lvl_max? { 8'h0, rd_ori_value[23:16], 16'h0} : {8'h0, soft_rd_number[8:1], 16'h0};
		else
			soft_slice_data <= {8'h0, soft_lvl_cnt[7:0], 16'h0};
	end	

	default:
		soft_slice_data <= 'h0;
	endcase
end
assign soft_delay_assert = (cal_current_st == CAL_SOFT_SLICE_RESTART);

always @(posedge clk)
begin
	if(~rst_n)
		soft_delay <= 'h0;
	else begin
		if(soft_delay_assert)
			soft_delay <= soft_delay + 1'b1;
		else
			soft_delay <= 'h0;
	end
end

assign cal_gate_save = (cal_current_st == CAL_SOFT_CHECK_LOOP_2);

always @(posedge clk)
begin
	if(~rst_n)
		cal_gate_leveling_last <= 1'b1;
	else begin
		case(cal_mode)
		4'b0100:
		begin
			if (restart || main_sel_reset || rd_page_rst)
				cal_gate_leveling_last <= 1'b0;
			else if (cal_gate_save)
				cal_gate_leveling_last <= cal_gate_leveling;
			else
				cal_gate_leveling_last <= cal_gate_leveling_last;
		end
		default:
		begin		
			if (main_sel_reset)
				cal_gate_leveling_last <= 1'b1;

			else if(cal_gate_save)
				cal_gate_leveling_last <= cal_gate_leveling;
			else
				cal_gate_leveling_last <= cal_gate_leveling_last;
		end
		endcase
	end
end

always @(posedge clk)
begin
	soft_cal_frst_reg <= enable_cal;
end

assign soft_cal_frst = ~soft_cal_frst_reg & enable_cal;

//////////////////
//Soft Read Leveling
//////////////////

assign rd_page_rst = (cal_current_st == CAL_SOFT_SWITCH_PAGE);

always@(posedge clk)
begin
	if(!rst_n || restart || main_sel_reset)
		rd_page_sw <= 1'b0;
	else begin
		if(cal_base_end_active && rom_fsm_done)
			rd_page_sw <= ~rd_page_sw;
		else
			rd_page_sw <= rd_page_sw;
	end
end

always@ (posedge clk)
begin
	if(!rst_n || restart || main_sel_reset || rd_page_rst)
	begin
		rd_first_delay_capture[1] <= 1'b0;
		rd_first_delay_capture[0] <= 1'b0;
	end
	else begin
		if(cal_gate_save && cal_gate_leveling) begin
			rd_first_delay_capture[1] <= 1'b1;
			rd_first_delay_capture[0] <= rd_first_delay_capture[1];
		end
		else begin
			rd_first_delay_capture[1] <= rd_first_delay_capture[1];
			rd_first_delay_capture[0] <= rd_first_delay_capture[1];
		end
	end
end

assign rd_first_delay = rd_first_delay_capture[1] & ~rd_first_delay_capture[0];

always@ (posedge clk)
begin
	if(rd_first_delay)
		rd_first_value <= soft_lvl_cnt;
	else
		rd_first_value <= rd_first_value;
end	

always@(posedge clk)
begin
	case(cal_mode)
	4'b0100:
	begin
		if (rd_page_sw && cmd_rmw_addr && !rom_data_out[3] && cal_loop_2_active)
			rd_address_mask <= 32'hFFFF_FFF0;
		else
			rd_address_mask <= 32'hFFFF_FFFF;
	end
	default:
	begin
		rd_address_mask <= 32'hFFFF_FFFF;
	end
	endcase
end

always@(posedge clk)
begin
	case(cal_mode)
	4'b0100:
	begin
		if (rd_page_sw && cmd_rmw_addr && !rom_data_out[3] && cal_loop_2_active)
			rd_mask <= 32'h00FF_00FF;
		else
			rd_mask <= 32'h0000_0000;
	end
	default:
	begin
		rd_mask <= 32'h0000_0000;
	end
	endcase
end


//////////////////
//Calibrator FSM
//////////////////

always @(posedge clk)
begin 
	if (~rst_n)
		cal_current_st <= CAL_IDLE;
	else
		cal_current_st <= cal_next_st;
end

always @(*)
begin
	cal_next_st = cal_current_st;
	
	case(cal_current_st)
	CAL_IDLE://0
	begin
		if(enable_cal)
			cal_next_st = CAL_START;
		else
			cal_next_st = CAL_IDLE;
	end
	CAL_START://1
			cal_next_st = CAL_FIRST_READ;
	CAL_FIRST_READ://2
	begin
		if(rom_cmd_data_ready)
			cal_next_st = CAL_LOAD_CNT;
		else
			cal_next_st = CAL_FIRST_READ;
	end
 	CAL_LOAD_CNT://3
	begin
		if(cal_loop_1_active_reg)
			cal_next_st = CAL_EXE_LOOP_1;
		else if(cal_loop_2_active_reg)
			cal_next_st = CAL_EXE_LOOP_2;
		else if(cal_loop_3_active_reg)
			cal_next_st = CAL_EXE_LOOP_3;
		else if(cal_base_end_active_reg)
			cal_next_st = CAL_EXE_BASE_END;
		else
			cal_next_st = CAL_EXE_BASE;
	end
	CAL_EXE_BASE://4
	begin	
	//force to enter CAL_EXE_LOOP_2 for DDR3 GL test
	//unless it is soft-cal
		case(cal_type[1])
		1'b0:
		begin
			if(rom_fsm_done && cal_mode[1])
				cal_next_st = CAL_DONE;
			else if(rom_fsm_done && !cal_mode[1]) 
				cal_next_st = CAL_EXE_LOOP_2;
			else
				cal_next_st = CAL_EXE_BASE;
		end
		1'b1:
		begin
			if(rom_fsm_done && cal_mode[0])
				cal_next_st = CAL_EXE_LOOP_1;
			else if(rom_fsm_done && (cal_mode[1] || cal_mode[2]))
				cal_next_st = CAL_EXE_LOOP_2;
			else
				cal_next_st = CAL_EXE_BASE;
		end
		default:
		begin
			if(rom_fsm_done && cal_mode[1])
				cal_next_st = CAL_DONE;
			else if(rom_fsm_done && !cal_mode[1]) 
				cal_next_st = CAL_EXE_LOOP_2;
			else
				cal_next_st = CAL_EXE_BASE;
		end
		endcase
	end
	CAL_CHECK_LOOP_1://5
	begin
		if (!cal_gate_leveling)
			cal_next_st = CAL_EXE_BASE_END;
		//enter this loop when j = 4 (cnt -1 = 3)
		else if (cal_gate_leveling && cal_loop_1_cnt == 3) 
			cal_next_st = CAL_EXE_LOOP_1;
		else
			cal_next_st = CAL_EXE_LOOP_2;
	end
	CAL_EXE_LOOP_1://6
	begin
		if (rom_cmd_cnt_empty && !cal_loop_1_active_reg)
			cal_next_st = CAL_START;
		else if(rom_fsm_done)
			cal_next_st = CAL_EXE_LOOP_2;
		else
			cal_next_st = CAL_EXE_LOOP_1;
	end	
	CAL_EXE_LOOP_2://7
	begin
		if (rom_cmd_cnt_empty && !cal_loop_2_active_reg)
			cal_next_st = CAL_START;
		else if(rom_fsm_done)
			cal_next_st = CAL_PRE_CHECK_LOOP_2;
		else
			cal_next_st = CAL_EXE_LOOP_2;
	end
	CAL_PRE_CHECK_LOOP_2:
		cal_next_st = CAL_CHECK_LOOP_2;
	CAL_CHECK_LOOP_2://8
	begin
		case(cal_type)
		2'b00:
		begin
			case(cal_mode)
			4'b1000:
			begin
				if(!cal_gate_leveling && ca_leveling_track)
					cal_next_st = CAL_EXE_BASE_END;
				else if(!cal_gate_leveling && !ca_leveling_track)
					cal_next_st = CAL_EXE_LOOP_1;
				else 
					cal_next_st = CAL_EXE_LOOP_2;
			end
			default:
			begin		
				if(!cal_gate_leveling)
					cal_next_st = CAL_EXE_BASE_END;
				else if(cal_loop_2_cnt == 8) 
					cal_next_st = CAL_EXE_LOOP_3;
				else
					cal_next_st =  CAL_EXE_LOOP_2;
			end
			endcase
		end
		default:
		begin
			case(cal_mode)
			4'b0100:
			begin
			if((!cal_gate_leveling && cal_gate_leveling_last) || soft_lvl_max)
				cal_next_st = CAL_EXE_BASE_END;
			else
				cal_next_st = CAL_SOFT_CHECK_LOOP_2;
			end
			default:
			begin
			if(cal_gate_leveling && !cal_gate_leveling_last)
				cal_next_st = CAL_EXE_BASE_END;
			else
				cal_next_st = CAL_SOFT_CHECK_LOOP_2;
			end
			endcase
		end 
		endcase	
	end
	CAL_SOFT_CHECK_LOOP_2:
	begin
		case(cal_mode)
		4'b0010:
		begin
			cal_next_st = CAL_EXE_LOOP_2;
		end
		default:
		begin
			if(cal_loop_2_cnt == 'd4)
				cal_next_st = CAL_EXE_LOOP_3;
			else
				cal_next_st = CAL_EXE_LOOP_2;
		end
		endcase
	end
	CAL_EXE_LOOP_3://9
	begin
		if (rom_cmd_cnt_empty && !cal_loop_3_active_reg)
			cal_next_st = CAL_START;
		else if(rom_fsm_done && !cal_type[1])
			cal_next_st = CAL_PRE_CHECK_LOOP_2;
		else if(rom_fsm_done && cal_type[1])
			cal_next_st = CAL_EXE_LOOP_2;
		else
			cal_next_st = CAL_EXE_LOOP_3;
	end
	CAL_EXE_BASE_END://10
	begin
		if (rom_cmd_cnt_empty && !cal_base_end_active_reg)
			cal_next_st = CAL_START;
		else if(rom_fsm_done && !cal_type[1])
			cal_next_st = CAL_DONE;
		else if(rom_fsm_done && cal_type[1])
			case(cal_mode[2])
			1'b1:
				cal_next_st = CAL_SOFT_SWITCH_PAGE;
			default:
				cal_next_st = CAL_SOFT_SLICE_RESTART;
			endcase
		else
			cal_next_st = CAL_EXE_BASE_END;
	end
	CAL_SOFT_SWITCH_PAGE:
	begin
		if(rd_page_sw)
			cal_next_st = CAL_EXE_LOOP_2;
		else
			cal_next_st = CAL_SOFT_SLICE_RESTART;
	end
	CAL_SOFT_SLICE_RESTART://11- only applicable for soft reset
	begin
		if(soft_delay == 'h1FF) begin
			if(soft_slice_cnt < cal_slice && cal_mode[0])
				cal_next_st = CAL_EXE_LOOP_1;
			else if(soft_slice_cnt < cal_slice && (cal_mode[1] || cal_mode[2]))
				cal_next_st = CAL_EXE_LOOP_2;
			else
				cal_next_st = CAL_DONE;
		end 
		else begin
			cal_next_st = CAL_SOFT_SLICE_RESTART;
		end
		
	end
	CAL_DONE://15
	begin
		if(restart)
			cal_next_st = CAL_IDLE;
		else
			cal_next_st = CAL_DONE;
	end
	default:
			cal_next_st = CAL_IDLE;
	endcase
end	
		
   

//////////////////
//i2c FSM
//////////////////

   always @(posedge clk)
     if (~rst_n)
       current_st <= ST_IDLE;
     else
       current_st <= next_st;

   always @(*)
     begin
	//defaults 
	next_st 	 = current_st;
	rd_en 		 = 1'b0;
	en_delay_cnt 	 = 1'b0;
	i2c_wr 		 = 1'b0;
	i2c_rd 		 = 1'b0;
	rom_sel 	 = 4'b0000;
	wr_rd_pass 	 = 1'b0;
	addr_wr 	 = 1'b0;
	rom_fsm_next_cmd = 1'b0;
 	rom_fsm_done 	 = 1'b0;	
	sel_reset	 = 1'b0;
	i2c_delay_assert = 1'b0;
	rmw_active 	 = 1'b0;
	
	case (current_st)
	  ST_IDLE :
	    begin
	       if (rom_fsm_start)
		 next_st = ST_START;
	    end

	  ST_START :
	    begin
		sel_reset = 1'b1;
		if(cal_loop_2_active_reg)
		begin
			next_st = ST_RD2_ROM;
			rom_sel = 4'b0010;
		end
		else if(cal_loop_1_active_reg)
		begin
			next_st = ST_RD2_ROM;
			rom_sel = 4'b0100;
		end
		else if(cal_loop_3_active_reg)
		begin
			next_st = ST_RD2_ROM;
			rom_sel = 4'b1000;
		end else
		begin
			next_st = ST_RD2_ROM;
			rom_sel = 4'b0001;
		end
	    end
	  
	  ST_CAL_MODE :
	    begin
		rom_fsm_next_cmd = 1'b1;
		if(!rom_cmd_cnt_empty && !cal_loop_1_active_reg 
				&& cal_loop_2_active_reg && !cal_loop_3_active_reg)
		begin
			next_st  = ST_RD0_ROM;
			rom_sel  = 4'b0010;
		end	 
		else if(!rom_cmd_cnt_empty && cal_loop_1_active_reg 
				&& !cal_loop_2_active_reg && !cal_loop_3_active_reg) 
		begin
			next_st  = ST_RD0_ROM;
			rom_sel  = 4'b0100;
		end	 
		else if(!rom_cmd_cnt_empty && !cal_loop_1_active_reg
				&& !cal_loop_2_active_reg && cal_loop_3_active_reg) 
		begin
			next_st  = ST_RD0_ROM;
			rom_sel  = 4'b1000;
		end	 
		else if(!rom_cmd_cnt_empty && !cal_loop_1_active_reg
				&& !cal_loop_2_active_reg && !cal_loop_3_active_reg) 
		begin
			next_st  = ST_RD0_ROM;
			rom_sel  = 4'b0001;
		end	 
		else
		begin
			next_st = ST_DONE;
			rom_sel = 4'b0000;
		end 
	    end // case: ST_CAL_MODE
		
	  ST_RD0_ROM:
	    begin
	       next_st = ST_RD1_ROM;
	    end

	  ST_RD1_ROM : //Read Data
	    begin
	       rd_en = 1'b1;
	       next_st = ST_RD2_ROM;	       
	    end
	  
	  ST_RD2_ROM : //Wait Data Ready
	    begin
	       en_delay_cnt = 1'b1;
	       if (delay_cnt == 4'h3) 
		 begin
		    next_st = ST_RD3_ROM;
		 end
	    end
	  
	  ST_RD3_ROM : //Check the bit for read/write condition to executive the commands. 
	    begin

	       if (cmd_wr)   			//WRITE DATA
		 next_st = ST_G_WR;
	       else if (cmd_rd)   		//READ DATA
		 next_st = ST_G_RD;
	       else if (cmd_polling_rd) 	//POLLILNG READ
		 next_st = ST_G_RD_POLL;
	       else if (cmd_wr_rd)   		//WRITE AND READ DATA. 
		 next_st = ST_G_WR1;
 	       else if (cmd_rmw)           	//RMW
                 next_st = ST_G_RMW;
	       else
		 next_st = ST_CAL_MODE;
	       
	    end // case: ST_RD3_ROM
	  

	  ////////////////////////////////////
	  // Generic - Write Command
	  ////////////////////////////////////
	  ST_G_WR :
	    begin
	       i2c_wr = 1'b1;
	       next_st = ST_G_WR_CHK_BUSY;
	    end

	  ST_G_WR_CHK_BUSY:
	    begin
	       if (i2c_busy)
		 next_st = ST_G_WR_CHK_DONE;
	    end

	  ST_G_WR_CHK_DONE:
	    begin
	       if (~i2c_busy & addr_wr_reg)       //Transtion to ST_RD3_ROM after complete write write. 
		 begin 
	    	 	if (i2c_delay_cnt == I2C_DELAY)
		 	begin
		    		next_st = ST_CAL_MODE;
		    		addr_wr = 1'b1;
			end
			else begin
				next_st = ST_G_WR_CHK_DONE; 
				i2c_delay_assert = 1'b1;
			end
		 end
	       
	       else if (~i2c_busy & ~addr_wr_reg) //Move to ST_G_WR to write data after complete write address. 
		 begin 
	    	 	//if (i2c_delay_cnt == I2C_DELAY)
		 	//begin
		    		next_st = ST_G_WR;
		    		addr_wr = 1'b1;
			//end
			//else begin
			//	next_st = ST_G_WR_CHK_DONE; 
			//	i2c_delay_assert = 1'b1;
			//end
		 end

	    end

	  //////////////////////////////////////
	  //Generic : Read Command
	  //////////////////////////////////////
	  ST_G_RD :
	    begin
	       i2c_rd = 1'b1;
	       next_st = ST_G_RD_CHK_BUSY;
	    end

	  ST_G_RD_CHK_BUSY:
	    begin
	       if (i2c_busy)
		 next_st = ST_G_RD_CHK_DONE;
	    end

	  ST_G_RD_CHK_DONE:
	    begin
	       if (~i2c_busy)
	    	 	if (i2c_delay_cnt == I2C_DELAY)
		 	begin
		    		next_st = ST_CAL_MODE;
			end
			else begin
				next_st = ST_G_RD_CHK_DONE; 
				i2c_delay_assert = 1'b1;
			end
	    end
	  
	  //////////////////////////////////////
	  //Generic : Read Polling
	  //////////////////////////////////////
	  ST_G_RD_POLL :
	    begin
	       i2c_rd = 1'b1;
	       next_st = ST_G_RD_POLL_CHK_BUSY;
	    end

	  ST_G_RD_POLL_CHK_BUSY:
	    begin
	       if (i2c_busy)
		 next_st = ST_G_RD_POLL_CHK_DONE;
	    end

	  ST_G_RD_POLL_CHK_DONE:
	    begin
	       if (~i2c_busy)
		 next_st = ST_G_RD_POLL_COMPARE;
	    end

	  ST_G_RD_POLL_COMPARE:
	    begin
	       if (masked_i2c_read_data == masked_rom_data_out) //Fix-ME
	    	 	if (i2c_delay_cnt == I2C_DELAY)
		 	begin
		    		next_st = ST_CAL_MODE;
			end
			else begin
				next_st = ST_G_RD_POLL_COMPARE; 
				i2c_delay_assert = 1'b1;
			end
	       else
	    	 	if (i2c_delay_cnt == I2C_DELAY)
		 	begin
		 	      next_st = ST_G_RD_POLL; //Continue Polling Read. 	       
			end
			else begin
				next_st = ST_G_RD_POLL_COMPARE; 
				i2c_delay_assert = 1'b1;
			end

	    end
	  

	  //////////////////////////////////////
	  //Write Leveling : Write & Read. 
	  //////////////////////////////////////
	  ST_G_WR1 :
	    begin
	       i2c_wr = 1'b1;
	       next_st = ST_G_WR1_CHK_BUSY;
	    end

	  ST_G_WR1_CHK_BUSY:
	    begin
	       if (i2c_busy)
		 next_st = ST_G_WR1_CHK_DONE;
	    end

	  ST_G_WR1_CHK_DONE:
	    begin
	       if (~i2c_busy)
		 next_st = ST_G_RD1;
	    end


	  ST_G_RD1 :
	    begin
	       i2c_rd = 1'b1;
	       next_st = ST_G_RD1_CHK_BUSY;
	    end

	  ST_G_RD1_CHK_BUSY:
	    begin
	       if (i2c_busy)
		 next_st = ST_G_RD1_CHK_DONE;
	    end

	  ST_G_RD1_CHK_DONE:
	    begin
	       if (~i2c_busy)
		 begin 
	    	 	if (i2c_delay_cnt == I2C_DELAY)
		 	begin
		    		next_st = ST_CAL_MODE;
		    		wr_rd_pass = (masked_i2c_read_data == masked_rom_data_out); //FIX ME
			end
			else begin
				next_st = ST_G_RD1_CHK_DONE; 
				i2c_delay_assert = 1'b1;
			end
		 end
	       
	    end
 	//////////////////////////////////////
 	//Generic : Read and Write Command 
 	/////////////////////////////////////
  	  ST_G_RMW :
            begin
               i2c_rd = 1'b1;
               next_st = ST_G_RMW_CHK_BUSY;
            end

          ST_G_RMW_CHK_BUSY:
            begin
               if (i2c_busy)
                 next_st = ST_G_RMW_CHK_DONE;
            end

          ST_G_RMW_CHK_DONE:
            begin
               if (~i2c_busy) begin
                  next_st = ST_G_RMW_W;
                  rmw_active = 1'b1;
               end

            end

          ST_G_RMW_W :
            begin
               i2c_wr = 1'b1;
               next_st = ST_G_RMW_W_CHK_BUSY;
               rmw_active = 1'b1;
            end

          ST_G_RMW_W_CHK_BUSY:
            begin
               rmw_active = 1'b1;

               if (i2c_busy)
                 next_st = ST_G_RMW_W_CHK_DONE;
            end
	  
	  ST_G_RMW_W_CHK_DONE:
            begin
               rmw_active = 1'b1;
               if (~i2c_busy & addr_wr_reg)       //Transtion to ST_RD3_ROM after complete write write. 
                 begin
		 	if (i2c_delay_cnt == I2C_DELAY)
                        begin
                    		addr_wr = 1'b1;
                    		next_st = ST_CAL_MODE;
			end else
			begin
				i2c_delay_assert = 1'b1;
				next_st = ST_G_RMW_W_CHK_DONE;
			end
	
                 end
               else if (~i2c_busy & ~addr_wr_reg) //Move to ST_G_WR to write data after complete write address. 
                 begin
                    next_st = ST_G_RMW_W;
                    addr_wr = 1'b1;
                 end

            end

	  ST_DONE :
	    begin 
	    	 if (i2c_delay_cnt == I2C_DELAY)
		 begin
			next_st = ST_IDLE;
		 	rom_fsm_done = 1'b1;
		end
		else begin
			next_st = ST_DONE;
			i2c_delay_assert = 1'b1;
		end
	    end

	  default : ;
	 
	endcase // case (current_st)
	
     end // always @ (*)


 always@(posedge clk)
 begin
	 if(~rst_n)
		 i2c_delay_cnt <= 'h0;
	 else
	 begin
		 if(i2c_delay_assert)
			 i2c_delay_cnt <= i2c_delay_cnt + 1;
		 else
			 i2c_delay_cnt <= 'h0;
	end
end

always @(posedge clk)
  if (~rst_n)
    addr_wr_reg <= 1'b0;
  else if (addr_wr)
    addr_wr_reg <= ~addr_wr_reg;
   
   
//Count the wait delay. 
always @(posedge clk)
  if (~rst_n)
    delay_cnt <= 4'h0;
  else if (en_delay_cnt)
    delay_cnt <= delay_cnt + 1'b1;
  else
    delay_cnt <= 4'h0;
   
always @(posedge clk)
  if (~rst_n)
    rom_sel_reg <= 4'h0;
  else if (current_st == ST_CAL_MODE | current_st == ST_START)
    rom_sel_reg <= rom_sel;

always @(posedge clk)
  if (~rst_n | restart)
    cal_done <= 1'b0;
  else if (cal_current_st == CAL_DONE)
    cal_done <= 1'b1;

always @(posedge clk)
  if (~rst_n)
    i2c_write_data_latch <= 32'h0;
  else if (i2c_wr)
    i2c_write_data_latch <= i2c_write_data;

   
always @(posedge clk)
begin

   i2c_write <= i2c_wr;
   i2c_read <= i2c_rd;
end

   assign i2c_soft_rst = 1'b0;
   assign num_bytes = I2C_TRX_BYTE;
   

 always @(posedge clk)
   if (~rst_n)
     wr_rd_pass_reg <= 1'b0;
   else if (wr_rd_pass)
     wr_rd_pass_reg <= 1'b1;
   

   `IP_MODULE_NAME(rom_parser) #(
       .DDR_TYPE(DDR_TYPE),
       .ROM_DATA_WIDTH(ROM_DATA_WIDTH),
       .ROM_OUTPUT_REG(ROM_OUTPUT_REG),
       .ROM_DATA_DEPTH0(ROM_DATA_DEPTH0),
       .ROM_DATA_DEPTH1(ROM_DATA_DEPTH1),
       .ROM_DATA_DEPTH2(ROM_DATA_DEPTH2),
       .ROM_DATA_DEPTH3(ROM_DATA_DEPTH3),
       .ROM_INIT_FILE0(ROM_INIT_FILE0),
       .ROM_INIT_FILE1(ROM_INIT_FILE1),
       .ROM_INIT_FILE2(ROM_INIT_FILE2),
       .ROM_INIT_FILE3(ROM_INIT_FILE3)
       )
     u_rom_parser
     (
      // Outputs
      .rom_rd_full                      (rom_rd_full), 
      .ram_data_out			(rom_data_out[ROM_DATA_WIDTH-1:0]),
      // Inputs
      .clk				(clk),
      .rst_n				(rst_n),
      .cal_type				(cal_type),
      .cal_mode				(cal_mode),
      .restart				(restart),
      .sel_reset			(rom_sel_reset),
      .sel				(rom_sel_reg),
      .rd_en				(rd_en_t));


  assign rd_en_dummy = (cal_base_active | cal_base_end_active) & rom_cmd_cnt_empty & rom_fsm_next_cmd;
  assign rd_en_t = rd_en | rd_en_dummy;
  assign rom_sel_reset = {1'b0, sel_reset};

   //== ASCII state decoding
   /*AUTOASCIIENUM("current_st", "current_ascii_st", "ST_")*/
   // Beginning of automatic ASCII enum decoding
`ifdef EFX_SIM
   reg [143:0]		current_ascii_st;	// Decode of current_st
   always @(current_st) begin
      case ({current_st})
	ST_IDLE:               current_ascii_st = "idle              ";
	ST_CAL_MODE:           current_ascii_st = "cal_mode          ";
	ST_RD0_ROM:            current_ascii_st = "rd0_rom           ";
	ST_RD1_ROM:            current_ascii_st = "rd1_rom           ";
	ST_RD2_ROM:            current_ascii_st = "rd2_rom           ";
	ST_RD3_ROM:            current_ascii_st = "rd3_rom           ";
	ST_G_WR:               current_ascii_st = "g_wr              ";
	ST_G_WR_CHK_BUSY:      current_ascii_st = "g_wr_chk_busy     ";
	ST_G_WR_CHK_DONE:      current_ascii_st = "g_wr_chk_done     ";
	ST_G_RD:               current_ascii_st = "g_rd              ";
	ST_G_RD_CHK_BUSY:      current_ascii_st = "g_rd_chk_busy     ";
	ST_G_RD_CHK_DONE:      current_ascii_st = "g_rd_chk_done     ";
	ST_G_RD_POLL:          current_ascii_st = "g_rd_poll         ";
	ST_G_RD_POLL_CHK_BUSY: current_ascii_st = "g_rd_poll_chk_busy";
	ST_G_RD_POLL_CHK_DONE: current_ascii_st = "g_rd_poll_chk_done";
	ST_G_RD_POLL_COMPARE:  current_ascii_st = "g_rd_poll_compare ";
	ST_G_WR1:              current_ascii_st = "g_wr1             ";
	ST_G_WR1_CHK_BUSY:     current_ascii_st = "g_wr1_chk_busy    ";
	ST_G_WR1_CHK_DONE:     current_ascii_st = "g_wr1_chk_done    ";
	ST_G_RD1:              current_ascii_st = "g_rd1             ";
	ST_G_RD1_CHK_BUSY:     current_ascii_st = "g_rd1_chk_busy    ";
	ST_G_RD1_CHK_DONE:     current_ascii_st = "g_rd1_chk_done    ";
	ST_DONE:               current_ascii_st = "done              ";
	default:               current_ascii_st = "%Error            ";
      endcase
   end
   // End of automatics
`endif
   
endmodule 

