//////////////////////////////////////////////////////////////////////////////
//           _____
//          / _______    Copyright (C) 2013-2020 Efinix Inc. All rights reserved.
//         / /       \
//        / /  ..    /   `IP_MODULE_NAME(ddr_calibration_parser).v
//       / / .'     /
//    __/ /.'      /     Description:
//   __   \       /      Parse configurations to DDR calibration contoller.
//  /_/ /\ \_____/ /
// ____/  \_______/
//
// *******************************
// Revisions:
// 1.0 Initial rev
//
// *******************************
//////////////////////////////////////////////////////////////////////////////
`resetall
`timescale 1ns / 1ps

module `IP_MODULE_NAME(ddr_calibration_parser) (
	input		clk,
	input		rst_n,
	output      ddr_slave_i2c_scl,      // DDR control I2C clock
    output      ddr_slave_i2c_sda,      // DDR control I2C data out
    input       ddr_slave_i2c_sda_in,   // DDR control I2C data in
	input		ddr_cal_auto_en,	// Enable auto-run for calibration
	input  [3:0]ddr_cal_auto_sel,	// Select leveling that require to run
	output [7:0]ddr_cal_auto_status,	// Indicate which leveling currently running
	input       pll_locked,             // PLL locked
    input       pll_ddr_locked,         // DDR PLL locked
    output      pll_rst_n,              // PLL active low reset
    output      pll_ddr_rst_n,          // DDR PLL active low reset
	output reg	auto_cal_done,		// Indicate status calibration done
	output reg	auto_cal_err		// Indicate status calibration error
);

	parameter [1:0]	DDR_TYPE		= 2'b00;		
	parameter 	    DDR_X16			= 1;
    parameter       ROM_DATA_DEPTH0 = 41;
    parameter       ROM_DATA_DEPTH1 = 29;
    parameter       ROM_DATA_DEPTH2 = 2;
    parameter       ROM_DATA_DEPTH3 = 2;
    parameter       ROM_INIT_FILE0  = "rom0_lpddr3_x16.hex";
    parameter       ROM_INIT_FILE1  = "rom1_lpddr3_x16.hex";
    parameter       ROM_INIT_FILE2  = "rom2_lpddr3_x16.hex";
    parameter       ROM_INIT_FILE3  = "rom3_lpddr3_x16.hex";

////////////////////////////////////////////////////
////AUTO CAL FSM
//////////////////////////////////////////////////////
localparam [3:0]	AUTO_IDLE	= 4'h0,
			AUTO_CHECK_MODE	= 4'h1,
			AUTO_CA_START	= 4'h2,
			AUTO_CA		= 4'h3,
			AUTO_CA_DONE	= 4'h4,
			AUTO_WR_START	= 4'h5,
			AUTO_WR		= 4'h6,
			AUTO_WR_DONE	= 4'h7,
			AUTO_GL_START	= 4'h8,
			AUTO_GL		= 4'h9,
			AUTO_GL_DONE	= 4'hA,
			AUTO_RD_START	= 4'hB,
			AUTO_RD		= 4'hC,
			AUTO_RD_DONE	= 4'hD,
			AUTO_CAL_ERROR	= 4'hE,
			AUTO_CAL_DONE	= 4'hF;

wire		g_rst_n;
reg	[3:0]	auto_st;
reg     [3:0]   auto_st_status;
reg	[3:0]	auto_next;
wire 	[7:0] 	cal_config;
wire 	[7:0] 	cal_status;
wire 		cal_done;
reg		enable_cal,
		restart;
reg 	[3:0]	cal_mode;
wire		delay_en;
reg	[2:0]	delay_cnt;
wire		delay_done;
wire		sda_out_w, 
		sda_in_w;
wire		cal_sel_err;
//Assignment
assign g_rst_n	  = rst_n & pll_locked & pll_ddr_locked;
assign cal_config = {cal_mode ,2'b00, enable_cal, restart};
assign cal_done	  = cal_status[0];
assign delay_done = (delay_cnt == 'h7);
assign delay_en   = restart;
assign ddr_cal_auto_status = {cal_status[3:0] , auto_st_status};
assign cal_sel_err = (DDR_TYPE == 2'b11) || (ddr_cal_auto_sel[2] && DDR_TYPE == 2'b10);

//FIXME
assign pll_rst_n     = 1'b1;
assign pll_ddr_rst_n = 1'b1;

//delay counter to hold reset for calibrator
always @(posedge clk)
begin
	if(!g_rst_n)
		delay_cnt <='h0;
	else
	begin
		if(delay_en)
			delay_cnt <= delay_cnt + 1'b1;
		else
			delay_cnt <= 'h0;
	end
end

//Moore SM state registers
always @(posedge clk)
begin	
	if(!g_rst_n)
		auto_st <= AUTO_IDLE;
	else
		auto_st <= auto_next;
end

//Next-state assignment
always @(*)
begin
	auto_next = auto_st;

	case(auto_st)
	AUTO_IDLE:
	begin
		if(ddr_cal_auto_en)
			auto_next = AUTO_CHECK_MODE;
		else
			auto_next = AUTO_IDLE;
	end
	AUTO_CHECK_MODE:
	begin
		if	((ddr_cal_auto_sel[3]) || cal_sel_err)
			//FIXME: temporarily remove CA leveling
			auto_next = AUTO_CAL_ERROR;
		else if (ddr_cal_auto_sel[2])
			auto_next = AUTO_WR_START;
		else if (ddr_cal_auto_sel[1])
			auto_next = AUTO_GL_START;
		else if (ddr_cal_auto_sel[0])
			auto_next = AUTO_RD_START;
		else
			auto_next = AUTO_CAL_ERROR;
	end
	AUTO_CA_START:
	begin
		if(delay_done)
			auto_next = AUTO_CA;
		else
			auto_next = AUTO_CA_START;
	end
	AUTO_CA:
	begin
		if(cal_done)
			auto_next = AUTO_CA_DONE;
		else
			auto_next = AUTO_CA;
	end
	AUTO_CA_DONE:
	begin
		if 	(ddr_cal_auto_sel[2])
			auto_next = AUTO_WR_START;
		else if (ddr_cal_auto_sel[1])
			auto_next = AUTO_GL_START;
		else if (ddr_cal_auto_sel[0])
			auto_next = AUTO_RD_START;
		else
			auto_next = AUTO_CAL_DONE;
	end
	AUTO_WR_START:
	begin
		if(delay_done)
			auto_next = AUTO_WR;
		else
			auto_next = AUTO_WR_START;
	end
	AUTO_WR:
	begin
		if(cal_done)
			auto_next = AUTO_WR_DONE;
		else
			auto_next = AUTO_WR;
	end
	AUTO_WR_DONE:
	begin
		if 	(ddr_cal_auto_sel[1])
			auto_next = AUTO_GL_START;
		else if (ddr_cal_auto_sel[0])
			auto_next = AUTO_RD_START;
		else
			auto_next = AUTO_CAL_DONE;
	end
	AUTO_GL_START:
	begin
		if(delay_done)
			auto_next = AUTO_GL;
		else
			auto_next = AUTO_GL_START;
	end
	AUTO_GL:
	begin
		if(cal_done)
			auto_next = AUTO_GL_DONE;
		else	
			auto_next = AUTO_GL;
	end
	AUTO_GL_DONE:
	begin
		if 	(ddr_cal_auto_sel[0])
			auto_next = AUTO_RD_START;
		else
			auto_next = AUTO_CAL_DONE;
	end
	AUTO_RD_START:
	begin
		if(delay_done)
			auto_next = AUTO_RD;
		else
			auto_next = AUTO_RD_START;
	end
	AUTO_RD:
	begin
		if(cal_done)
			auto_next = AUTO_RD_DONE;
		else
			auto_next = AUTO_RD;
	end
	AUTO_RD_DONE:
	begin
		auto_next = AUTO_CAL_DONE;
	end
	AUTO_CAL_ERROR:
	begin
		if(!ddr_cal_auto_en)
			auto_next = AUTO_IDLE;
		else
			auto_next = AUTO_CAL_ERROR;
	end
	AUTO_CAL_DONE:
	begin
	 	if(!ddr_cal_auto_en)
                        auto_next = AUTO_IDLE;
                else
			auto_next = AUTO_CAL_DONE;
	end
	default:
	begin
		auto_next = AUTO_IDLE;
	end
	endcase
end

//Output assignment
always@ (auto_st)
begin
	case(auto_st)
        AUTO_IDLE:
        begin
		enable_cal 	= 1'b0;
		restart		= 1'b0;
		cal_mode	= 4'b0000;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_CHECK_MODE:
	begin
		enable_cal 	= 1'b0;
		restart		= 1'b0;
		cal_mode	= 4'b0000;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_CA_START:
	begin
		enable_cal 	= 1'b0;
		restart		= 1'b1;
		cal_mode	= 4'b1000;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_CA:
	begin
		enable_cal 	= 1'b1;
		restart		= 1'b0;
		cal_mode	= 4'b1000;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_CA_DONE:
	begin
		enable_cal 	= 1'b0;
		restart		= 1'b1;
		cal_mode	= 4'b0000;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_WR_START:
	begin
		enable_cal 	= 1'b0;
		restart		= 1'b1;
		cal_mode	= 4'b0010;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_WR:
	begin
		enable_cal 	= 1'b1;
		restart		= 1'b0;
		cal_mode	= 4'b0010;
		auto_st_status  = 4'b0100;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_WR_DONE:
	begin
		enable_cal 	= 1'b0;
		restart		= 1'b1;
		cal_mode	= 4'b0000;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_GL_START:
	begin
		enable_cal 	= 1'b0;
		restart		= 1'b1;
		cal_mode	= 4'b0001;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_GL:
	begin
		enable_cal 	= 1'b1;
		restart		= 1'b0;
		cal_mode	= 4'b0001;
		auto_st_status  = 4'b0010;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_GL_DONE:
	begin
		enable_cal 	= 1'b1;
		restart		= 1'b1;
		cal_mode	= 4'b0000;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_RD_START:
	begin
		enable_cal 	= 1'b0;
		restart		= 1'b1;
		cal_mode	= 4'b0100;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_RD:
	begin
		enable_cal 	= 1'b1;
		restart		= 1'b0;
		cal_mode	= 4'b0100;
		auto_st_status  = 4'b0001;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_RD_DONE:
	begin
		enable_cal 	= 1'b1;
		restart		= 1'b1;
		cal_mode	= 4'b0000;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	AUTO_CAL_ERROR:
	begin
		enable_cal 	= 1'b0;
		restart		= 1'b0;
		cal_mode	= 4'b0000;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b1;
	end
	AUTO_CAL_DONE:
	begin
		enable_cal 	= 1'b0;
		restart		= 1'b0;
		cal_mode	= 4'b0000;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b1;
		auto_cal_err	= 1'b0;
	end
	default:
	begin
		enable_cal 	= 1'b0;
		restart		= 1'b0;
		cal_mode	= 4'b0000;
		auto_st_status  = 4'b0000;
		auto_cal_done	= 1'b0;
		auto_cal_err	= 1'b0;
	end
	endcase
end


