        .ROM_INIT_FILE1		(ROM_INIT_FILE1),
        .ROM_INIT_FILE2		(ROM_INIT_FILE2),
        .ROM_INIT_FILE3		(ROM_INIT_FILE3)
) u_top_ddr_calibration_wrapper (
		.sda_out	(sda_out_w),
                .scl_out      	(ddr_slave_i2c_scl),
		.sda_in		(sda_in_w),
                .scl_in       	(ddr_slave_i2c_scl),
		.clk            (clk),
                .i2c_clk        (clk),
                .rst_n          (g_rst_n),
                .config_reg0    (cal_config),
                .status_reg0    (cal_status),
		.status_reg1	(),
                .control_led    () 			//optional for debug
);

endmodule
