`resetall
`timescale 1ns / 1ps

module `IP_MODULE_NAME(top_ddr_calibration_wrapper) 
#(
	parameter [1:0] DDR_TYPE		= 2'b00,
	parameter	DDR_X16			= 0,
	parameter       I2C_CMD_BYTE_WIDTH      = 8,
        parameter [7:0] I2C_TRX_BYTE            = 8'h5,
        parameter       ROM_DATA_DEPTH0         = 38,
        parameter       ROM_DATA_DEPTH1         = 16,
        parameter       ROM_DATA_DEPTH2         = 13,
        parameter       ROM_DATA_DEPTH3         = 4,
        parameter       ROM_INIT_FILE0          = "rom0.hex",
        parameter       ROM_INIT_FILE1          = "rom1.hex",
        parameter       ROM_INIT_FILE2          = "rom2.hex",
        parameter       ROM_INIT_FILE3          = "rom3.hex"

) (
   output control_led,
   //////////////////////////////
   //I2c Interface (DDR IP Core) 
   //Outputs
   output sda_out,
   output scl_out,
   //Inputs 
   input sda_in,
   input scl_in,


   //////////////////////////////
   //System Clock & Reset
   input clk,     // 8Mhz clock from pll
   input i2c_clk, // 8Mhz clock from pll
   input rst_n,	  // external resetn that AND wih pll_locked	
  
   //////////////////////////////


   //////////////////////////////
   //Configuration Register
   input [7:0] config_reg0,
   //////////////////////////////
   //Status Register
   output [7:0] status_reg1,
   output [7:0] status_reg0
   //TEMPFIX
   );

/////////////////////////////////
//Internal Signals 
   wire 	restart;
   wire 	enable_cal;
   wire [3:0] 	cal_mode;
   wire [1:0]	cal_type;
   wire 	i2c_busy;
   wire [31:0] 	i2c_read_data;
   wire 	i2c_read;
   wire 	i2c_write;
   wire 	i2c_soft_rst;
   wire [31:0] 	i2c_write_data;
   wire [7:0] 	command_byte;
   wire [7:0] 	num_bytes;
   wire 	i2c_rxak;
   wire 	cal_done;
   wire [7:0] 	i2c_slave_addr;
   wire 	wr_rd_pass;
   wire	[6:0]	cal_status_reg;
   wire [7:0]	cal_status_reg2;
   wire [1:0]	cal_type_1;
   wire [2:0]   cal_slice;

/////////////////////////////////
//RTL

   //Control registers
   assign restart 	= config_reg0[0];
   assign enable_cal 	= config_reg0[1];
   assign control_led 	= config_reg0[2];
   //assign cal_type 	= {cal_type_1, config_reg0[3]};
   assign cal_type	= cal_type_1;
   assign cal_mode 	= config_reg0[7:4];
   
   //Status registers. 
   
   assign status_reg0[0] = cal_done;
   assign status_reg0[7:1] = cal_status_reg[6:0];
   assign status_reg1 = cal_status_reg2;
   
   //DDR Calibration Core I2C2APB Core. 
   assign i2c_slave_addr = 8'h82;
   
////////////////////////////////
//Calibration Controller.
////////////////////////////////
  `IP_MODULE_NAME(cal_controller) #(
	.DDR_TYPE(DDR_TYPE),
	.I2C_CMD_BYTE_WIDTH(I2C_CMD_BYTE_WIDTH),
	.I2C_TRX_BYTE(I2C_TRX_BYTE),
	.ROM_DATA_DEPTH0(ROM_DATA_DEPTH0),
	.ROM_DATA_DEPTH1(ROM_DATA_DEPTH1),
	.ROM_DATA_DEPTH2(ROM_DATA_DEPTH2),
	.ROM_DATA_DEPTH3(ROM_DATA_DEPTH3),
	.ROM_INIT_FILE0(ROM_INIT_FILE0),
	.ROM_INIT_FILE1(ROM_INIT_FILE1),
	.ROM_INIT_FILE2(ROM_INIT_FILE2),
	.ROM_INIT_FILE3(ROM_INIT_FILE3)
  ) u_cal_controller (
     // Outputs
     .cal_done				(cal_done),
     .cal_status_reg			(cal_status_reg),
     .cal_status_reg2			(cal_status_reg2),
     .wr_rd_pass_reg                    (wr_rd_pass), 
     .i2c_write_data			(i2c_write_data[31:0]),
     .command_byte			(command_byte[7:0]),
     .num_bytes				(num_bytes[7:0]),
     .i2c_read				(i2c_read),
     .i2c_write				(i2c_write),
     .i2c_soft_rst			(i2c_soft_rst),
     // Inputs
     .clk				(clk),
     .rst_n				(rst_n),
     .restart				(restart),
     .enable_cal			(enable_cal),
     .cal_type				(cal_type),
     .cal_mode				(cal_mode[3:0]),
     .cal_slice				(cal_slice),
     .i2c_busy				(i2c_busy),
     .i2c_read_data			(i2c_read_data));
   
      

/////////////////////////////////
//I2C Master Controller
/////////////////////////////////

   `IP_MODULE_NAME(i2c_master_ctl) u_i2c_master_ctl
     (
      // Outputs
      .scl_out				(scl_out),
      .sda_out				(sda_out),
      .data_out				(i2c_read_data),
      .busy				(i2c_busy),
      .i2c_rxak				(i2c_rxak),
      // Inputs
      .sda_in				(sda_in),
      .scl_in				(scl_in),
      .i2c_slave_addr			(i2c_slave_addr[7:0]),
      .din				(i2c_write_data),
      .i2c_clk				(i2c_clk),
      .rst				(~rst_n),
      .command_byte			(command_byte),
      .num_bytes			(num_bytes[7:0]),
      .read				(i2c_read),
      .write				(i2c_write),
      .i2c_soft_rst			(i2c_soft_rst));
   

	generate
	begin
	//LPDDR3_X32
	if(DDR_TYPE == 2'b00 && DDR_X16 == 0) begin
		assign cal_type_1 = 2'b10;
		assign cal_slice  = 3'h4; 
	end	
	//LPDDR3_X16
	else if(DDR_TYPE == 2'b00 && DDR_X16 == 1) begin 
		assign cal_type_1 = 2'b10;
		assign cal_slice  = 3'h2; 
	end	

	//DDR3_X32
	else if(DDR_TYPE == 2'b01 && DDR_X16 == 0) begin
		assign cal_type_1 = 2'b11;
		assign cal_slice  = 3'h4; 
	end	

	//DDR3_x16
	else if(DDR_TYPE == 2'b01 && DDR_X16 == 1) begin
		assign cal_type_1 = 2'b11;
		assign cal_slice  = 3'h2; 
	end	

	//LPDDR2_X32
	else if(DDR_TYPE == 2'b10 && DDR_X16 == 0) begin
		assign cal_type_1 = 2'b10;
		assign cal_slice  = 3'h4; 
	end	
	
	//LPDDR2_X16
	else if(DDR_TYPE == 2'b10 && DDR_X16 == 1) begin
		assign cal_type_1 = 2'b10;
		assign cal_slice  = 3'h2; 
	end	

	//RESERVED
	else begin
		assign cal_type_1 = 2'b00;
		assign cal_slice = 3'h0;
	end
	end
	endgenerate
   
endmodule 
