`resetall
`timescale 1ns / 1ps
//`include "i2c_master_defines.h"
  

  module `IP_MODULE_NAME(i2c_master_ctl) #(
			   parameter CMD_BYTE_WIDTH = 8,
			   parameter DATA_BYTE_WIDTH = 32
			   )
   (
    //I2c Interfacing. 
    output 			      scl_out, 
    output 			      sda_out,
    input 			      sda_in,
    input 			      scl_in,
    
    
    //outputs
    output wire [DATA_BYTE_WIDTH-1:0] data_out,	//32-bits data to Microcontroller/User Logic. 
    output wire 		      busy,	//i2c busy.
    output wire 		      i2c_rxak, //i2c acknowledge.
    
							
    //inputs
    input [7:0] 		      i2c_slave_addr,	//i2c slave address register.
    input [DATA_BYTE_WIDTH-1:0]       din,		//32-bits from Microcontroller / User Logic FSM. 
    input 			      i2c_clk,		//2MHz for 100kHz I2c.
							//8MHz for 400kHz I2c. 
    input 			      rst,		//Sync Reset.
   
    //Register Interface
    input [CMD_BYTE_WIDTH-1:0] 	      command_byte,	//Command Bytes 
    input [7:0] 		      num_bytes,	//Number of Read/Write Bytes. 
    input 			      read,		//Read Strobe. 
    input 			      write,		//Write Strobe. 
    input 			      i2c_soft_rst	//I2c Soft Reset. 
   );

  
 

// Local Parameter (FSM)
   //== State enumeration
   parameter [3:0] // synopsys enum state_info
     IDLE_ST          = 4'h0,
     START_GEN0_ST    = 4'h1,
     WRITE_DAT0_ST    = 4'h2,
     START_GEN1_ST    = 4'h3,
     WRITE_DAT1_ST    = 4'h4, // Command Byte Sequence (READ)
     RESTART_ST       = 4'h5, // Generate a restart sequence
     WRITE_DAT2_ST    = 4'h6, // READ THE DATA
     STOP_GEN_ST      = 4'h7,
     DONE_ST          = 4'h8;
   
	      
   
	      
//internal signals
   //== State variables
   reg [3:0] /* synopsys enum state_info */ 
	     current_st; /* synopsys state_vector current_st */ 
   reg [3:0] /* synopsys enum state_info */			      
	     next_st;
   
   reg [7:0] byte_cnt;  //Byte Counter.    
  
   reg [7:0]  MIDR; //I2d Data Register Inbound
   reg [7:0]  MBCR; //Control Register
   wire [7:0] MBSR; //Status Register. 
   wire [7:0] MODR; //I2c Data Register Outbound
   wire       uc_wr_data;
   wire       uc_rd_data;
   reg [1:0]  mbcr_write0;
   reg 	      mbcr_write;
   wire       wuc0;
   reg 	      wuc1;
   wire       xfer_complete0;
   reg 	      xfer_complete1;
   
   reg 	      restart;
   reg 	      mbcr_write_a;
   reg [1:0]  uc_wr_data0;
   reg [1:0]  uc_rd_data0;
   reg [7:0]  i2c_slave_addr0;
   wire       read_p,write_p;   
   reg [3:0]  soft_rst_reg;
   wire       soft_rst;
   reg [31:0] data_out0;
   
   
   //////////////////////////////////////////////////////////////////////////////////////
   //Sensor Status update.
   //This state machine is actually used to solve performance issues caused by firmware.
   ///////////////////////////////////////////////////////////////////////////////////////

   //I2C Receive Acknowledge Bit
   assign i2c_rxak = MBSR[0];
      
   // I2c Busy status
   assign    busy = MBSR[5];
   
   /////////////////////////////////////
   //Sychronizer
   //Fast2Slow Domain
   /////////////////////////////////////
   `IP_MODULE_NAME(pulse_gen) u_pgfts_wrflag
     (
      // Outputs
      .data_out				(write_p),
      // Inputs
      .clk				(i2c_clk),
      .rst                              (rst),
      .data_in				(write));
   
   `IP_MODULE_NAME(pulse_gen) u_pgfts_rdflag
     (
      // Outputs
      .data_out				(read_p),
      // Inputs
      .clk				(i2c_clk),
      .rst                              (rst),
      .data_in				(read));
   
   /////////////////////////////
   //I2c Controller
   /////////////////////////////
   
   `IP_MODULE_NAME(i2c_mstrslv_ctl) u_i2c_mstrslv_ctl
     (
      // Outputs
      .MBSR				(MBSR[7:0]),		//I2c Status Register.
      .MODR				(MODR[7:0]),		//I2c Data Register
      .sda_out				(sda_out),		//SDA output drive control.
      .scl_out				(scl_out),		//SCL output drive control.
      // Inputs
      .MBCR				(MBCR[7:0]),		//i2c control register.
      .MADR				(i2c_slave_addr0),	//I2c Slave Address Register
      .MIDR				(MIDR[7:0]),		//I2c Data Register Inbound.
      .sda_in				(sda_in),		//SDA Input.
      .scl_in				(scl_in),		//SCL input.
      .mbcr_wr	         		(mbcr_write0[1]),	//MBCR is being written
      .uc_rd_data			(uc_rd_data),		//Status uC read data register.
      .uc_wr_data			(uc_wr_data),		//Status uC wrote data register.
      .mif_clr				(1'b0),			//Clear Interrupt Bit
      .mal_clr				(1'b0),			//Clear Arbitration Lost Bit.
      .clk				(i2c_clk));		//2MHz clock.
   

   ///////////////////////////////
   //I2c Slave Address.
   ///////////////////////////////
   always @(posedge i2c_clk)
     if (rst)
       i2c_slave_addr0 <= 8'h00;
     else /*if (read_p || write_p)*/ //Fix-Me !!!
       i2c_slave_addr0 <= i2c_slave_addr;
   


   ///////////////////////////////
   //I2c Master Controller States
   ///////////////////////////////
   always @(posedge i2c_clk)
     begin
	if (rst )
	  current_st <= IDLE_ST;
	else
	  current_st <= next_st;
     end
   
   
   
   always @(*)
     begin
	next_st = IDLE_ST;
	case(current_st)
	  
	  IDLE_ST: begin
	     if (write_p) 
	       next_st = START_GEN0_ST;  //I2c Master XMIT 
	     else if (read_p)
	       next_st = START_GEN1_ST;  //I2c Master Receive
	     else
	       next_st = IDLE_ST;
	  end
	  
	  START_GEN0_ST: begin //Generate Start Condition (XMIT)
	     if (write_p || read_p)
	       begin 
      		  next_st = STOP_GEN_ST;   
	       end
	     else if (MBCR[7] == 1'b1) // Wait for transfer complete - MCF==1. 
	       next_st = WRITE_DAT0_ST;
	     else
	       next_st = START_GEN0_ST;
	  end
	  
	  START_GEN1_ST: begin //Generate Start Condition (RECEIVER)
	     if (write_p || read_p)
	       begin 
      		  next_st = STOP_GEN_ST;   
	       end
	     
	     else if (MBCR[7] == 1'b1) // Wait for xfer complete bit true
	       next_st = WRITE_DAT1_ST;
	     else
	       next_st = START_GEN1_ST;
	  end
	  
	  WRITE_DAT0_ST: begin
	     
	     if (write_p || read_p)
	       begin 
      		  next_st = STOP_GEN_ST;  
	       end
	     else if (byte_cnt == num_bytes && MBSR[7] == 1'b1) //Wait for (data) xfer bit true
	       begin
		  next_st = STOP_GEN_ST;
	       end
	     
	     
	     else
	       begin
		  next_st = WRITE_DAT0_ST;
	       end // else: !if(byte_cnt == num_bytes && MBSR[7] == 1'b1)
	     
	     
	     
	  end
	  
	  WRITE_DAT1_ST: begin
	     if (write_p || read_p)
	       begin 
      		  next_st = STOP_GEN_ST;   
	       end
	     
	     else if ( /*i2c_slave_addr0 == `SLAVE_ADDR  &*/ byte_cnt == num_bytes && MBSR[7] == 1'b1) //Wait for (data) xfer bit true (command register)
	       begin
		  next_st = RESTART_ST;
	       end
	     
	  
	     
	     else
	       begin
		  next_st = WRITE_DAT1_ST;
	       end // else: !if(...
	     
	     
	  end // case: WRITE_DAT1_ST
	  
	  RESTART_ST : begin //Generate a restart sequence for read.
	     if (MBCR[7] == 1'b1)
	       next_st = WRITE_DAT2_ST;
	     else
	       next_st = RESTART_ST;
	  end
	  
	  WRITE_DAT2_ST: begin
	     if (read_p || write_p)
	       begin
		  next_st = STOP_GEN_ST;
	 
	       end
	     else if ( (byte_cnt == num_bytes /*-(CMD_BYTE_WIDTH/8)*/) && MBSR[7] == 1'b1) //Wait for (data) xfer bit true
	       begin
		  next_st = STOP_GEN_ST;
		 
	       end
	     
             
	     else
	       begin
		  next_st = WRITE_DAT2_ST;
		 
	       end // else: !if(byte_cnt == (num_bytes -1) && MBSR[7] == 1'b1)
	     
	  end // case: WRITE_DAT2_ST
	  
	  
	  STOP_GEN_ST: begin 
	     if (MBSR[7] == 1'b0) //Wait for master to exit wait state
	       next_st = DONE_ST;
	     else
	       next_st = STOP_GEN_ST;
	  end
	  
	  DONE_ST: begin          //Check for MBB status flag.
	     if (MBSR[5] == 1'b0) //Wait for bus not busy
	       next_st = IDLE_ST;
	     else
	       next_st = DONE_ST;
	  end
  
	  default : next_st = IDLE_ST;
	endcase // case (current_st)	
     end // always @ (*)
   

     
//I2c Master Controller (WRITE-RESTART-READ)...   
//Note : Master Restart Read - This routine writes out the header and one data byte then generates a
// restart with another header and reads the data (based on the num_bytes setting)....
   
   //Send data out!
   always @(posedge i2c_clk)
     if (rst)
       MIDR <= 8'h00;
     else if (write_p || read_p)
       MIDR <= {i2c_slave_addr0[7:1],1'b0}; //Header + Write
     else if (current_st == RESTART_ST) //READ_P SEQ.
       MIDR <= {i2c_slave_addr0[7:1],1'b1}; //Header + Read_p
     else if (MBSR[3] == 1'b1) //Wait Microcontroller to read/write to data register MBDR.
       //if (i2c_slave_addr0 == `SLAVE_ADDR )
       begin
	  if (byte_cnt == 0)
	    MIDR <= command_byte[7:0];
	  else if (byte_cnt == 1)
	    MIDR <= din[7:0];
	  else if (byte_cnt == 2)
	    MIDR <= din[15:8];
	  else if (byte_cnt == 3)
	    MIDR <= din[23:16];
	  else if (byte_cnt == 4)
	    MIDR <= din[31:24];
       end // if (MBSR[3] == 1'b1)
   
   
	    
   	   
   
   //I2c Master Control Register
   always @(posedge i2c_clk)
     if (rst | soft_rst)
       MBCR <= 8'h00;
     else if ( (current_st == WRITE_DAT0_ST || current_st == WRITE_DAT1_ST || current_st == WRITE_DAT2_ST ) && (read_p || write_p) ) 
       MBCR <= 8'hc0; //Generate a stop conditon...
     else if (write_p)
       MBCR <= 8'hf0; // Generate Start Conditon (write cycle)
     else if (read_p)
       MBCR <= 8'hf0; // Generate Start Condition
     else if ( current_st == RESTART_ST)
       MBCR <= 8'hE4; //Generate a restart read with ack
     else if (current_st == WRITE_DAT2_ST && byte_cnt == (num_bytes -1) && MBCR !== 8'hc0 && MBSR[7] == 1'b1) //4
       MBCR <= 8'he8; // Generate(end multibyte read cycle noack!)
     else if ( (current_st == WRITE_DAT2_ST) && byte_cnt == (num_bytes ) && MBSR[7] == 1'b1 ) //5
       MBCR <= 8'hc0; // Generate a STOP Condition
     else if ( (current_st == WRITE_DAT0_ST) && byte_cnt == (num_bytes) && MBSR[7] == 1'b1 )
       MBCR <= 8'hc0; // Generate a STOP Condition
   
   
   
   always @(posedge i2c_clk)
     begin
	if (rst)
	  restart <= 1'b0;
	else
          restart <= (current_st == RESTART_ST);
     end
   
   //MBCR is being written?
   always @(posedge i2c_clk)
     if (rst)
       mbcr_write0 <= 2'b00;
     else if (write_p || read_p  ||  ( byte_cnt == (num_bytes) && MBSR[7] == 1'b1 ) || ( current_st == RESTART_ST && ~restart ))
       mbcr_write0 <= 2'b11;
     else if ( (current_st == WRITE_DAT2_ST) && byte_cnt == (num_bytes ) && MBSR[7] == 1'b1 ) //5
       mbcr_write0 <= 2'b11;
     else if  (current_st == WRITE_DAT2_ST && byte_cnt == (num_bytes -1)  && MBCR !== 8'hc0 && MBSR[7] == 1'b1 ) //4
       mbcr_write0 <= 2'b11;     
     else
       mbcr_write0 <= {mbcr_write0[0],1'b0};

   
   always @(posedge i2c_clk)
     if (rst)
       begin
	  mbcr_write_a <= 1'b0;
	  mbcr_write   <= 1'b0;
       end
     else    
       begin 
	  mbcr_write_a <= mbcr_write0[1];
	  mbcr_write <= mbcr_write_a;
       end
   
   
   assign wuc0 = MBSR[3];
   assign xfer_complete0 = MBSR[7];
   
   always @(posedge i2c_clk)
     if (rst)
       begin
	  wuc1 <= 1'b0;
	  xfer_complete1 <= 1'b0;
       end
     else
       begin
	  wuc1 <= wuc0;
	  xfer_complete1 <= xfer_complete0;
      end
   
   
   //I2c Write Strobe
   always @(posedge i2c_clk)
     if (rst)
       uc_wr_data0 <= 2'b0;
     else if (current_st == WRITE_DAT0_ST && (wuc0 && ~wuc1) && byte_cnt <= (num_bytes )) //wuc =1, Master in wait_uC state
       uc_wr_data0 <= 2'b11;
     else if ( /*i2c_slave_addr0 == `SLAVE_ADDR    &*/ current_st == WRITE_DAT1_ST && (wuc0 && ~wuc1) && byte_cnt < (num_bytes /*-(CMD_BYTE_WIDTH/8)*/ ) ) //wuc =1, Master in wait_uC state
       uc_wr_data0 <= 2'b11; //A write strobe during read sequence...
   
     else if ( read_p || current_st == RESTART_ST) //Strobe Write data Flags...
       uc_wr_data0 <=  2'b11;
     else
       uc_wr_data0 <= {uc_wr_data0[0],1'b0};
   
   assign uc_wr_data = uc_wr_data0[1];
   
   //I2c Read Strobe
   always @(posedge i2c_clk)
     if (rst)
       uc_rd_data0 <= 2'b00;
     else if (current_st == WRITE_DAT2_ST && (xfer_complete0 && ~xfer_complete1)  && byte_cnt < (num_bytes-(CMD_BYTE_WIDTH/8) +2) )
       uc_rd_data0 <= 2'b11;
     else
       uc_rd_data0 <= {uc_rd_data0[0],1'b0};

   assign uc_rd_data = uc_rd_data0[1];
   
   
   always @(posedge i2c_clk)
     if (rst)
       byte_cnt <= 8'h0;
     else if (current_st == WRITE_DAT0_ST)
       if (xfer_complete0 && ~xfer_complete1)
	 byte_cnt <= byte_cnt + 1;
       else
	 byte_cnt <= byte_cnt;
     else if (current_st == WRITE_DAT1_ST)
       if (xfer_complete0 && ~xfer_complete1)
	 byte_cnt <= byte_cnt + 1;
       else
	 byte_cnt <= byte_cnt;
     else if (current_st == WRITE_DAT2_ST)
       if (~xfer_complete0 && xfer_complete1)
	 byte_cnt <= byte_cnt + 1;
       else
	 byte_cnt <= byte_cnt;
     else 
       byte_cnt <= 8'h0;
   

   
   always @(posedge i2c_clk)
     if (rst)
       data_out0 <= 32'h0000_0000;
     else if (current_st == WRITE_DAT2_ST && (xfer_complete0 && ~xfer_complete1))
       data_out0 <= {MODR, data_out0[31:8]};

   

   assign     data_out = data_out0;
   
////////////////////
// Soft Reset.
////////////////////

   always @(posedge i2c_clk or posedge i2c_soft_rst)
     if (rst | i2c_soft_rst)
       soft_rst_reg <= 4'hf;
     else
       soft_rst_reg <= {soft_rst_reg[2:0], 1'b0};

   assign soft_rst = soft_rst_reg[3];


   /*AUTOASCIIENUM("current_st", "current_st_ascii", "_ST")*/
   // Beginning of automatic ASCII enum decoding
   reg [79:0]		current_st_ascii;	// Decode of current_st
   always @(current_st) begin
      case ({current_st})
	IDLE_ST:       current_st_ascii = "idle      ";
	START_GEN0_ST: current_st_ascii = "start_gen0";
	WRITE_DAT0_ST: current_st_ascii = "write_dat0";
	START_GEN1_ST: current_st_ascii = "start_gen1";
	WRITE_DAT1_ST: current_st_ascii = "write_dat1";
	RESTART_ST:    current_st_ascii = "restart   ";
	WRITE_DAT2_ST: current_st_ascii = "write_dat2";
	STOP_GEN_ST:   current_st_ascii = "stop_gen  ";
	DONE_ST:       current_st_ascii = "done      ";
	default:       current_st_ascii = "%Error    ";
      endcase
   end
   // End of automatics

endmodule // i2c_master_ctrl
