//           _____       
//          / _______    Copyright (C) 2013-2020 Efinix Inc. All rights reserved.
//         / /       \   
//        / /  ..    /   `IP_MODULE_NAME(i2c_mstrslv_ctl).v
//       / / .'     /    
//    __/ /.'      /     Description:
//   __   \       /      i2c slave  
//  /_/ /\ \_____/ /     
// ____/  \_______/      
