`resetall
`timescale 1ns / 1ps


module `IP_MODULE_NAME(pulse_gen)
    (
     //outputs.
     output reg data_out,     //slow clock signal

     //inputs
     input 	clk,           //system clock
     input 	rst,           //active high reset. 
     input 	data_in        //fast clock signal
     );
//Parameters
   parameter DETECT_POS = 1;
   
//Internal Signals
   wire 	async_set;
   reg [1:0] 	data0;
   reg [2:0] 	data_sync;
   
   wire 	data_sync_pos;
   
   assign async_set = data_in;
   
   always @(posedge clk or posedge async_set)
     if (async_set)
       data0 <= 2'b11;   
     else if (rst)
       data0 <= 2'b0;
     else
       data0 <= {data0[0],1'b0};
   

   always @(posedge clk)
     if (rst)
       data_sync <= 3'b00;
     else
       data_sync <= {data_sync[1:0],data0[1]};

   generate
      if (DETECT_POS == 1)
	assign data_sync_pos = ~data_sync[2] && data_sync[1];
      else
	assign data_sync_pos = ~data_sync[1] && data_sync[2];
   endgenerate
   
   always @(posedge clk)
     if (rst)
       data_out <= 1'b0;
     else if (data_sync_pos)
       data_out <= 1'b1;
     else
       data_out <= 1'b0;
   
   
endmodule // pulse_gen_fts
