`resetall
`timescale 1ns / 1ps


module `IP_MODULE_NAME(rom_parser)
  #(	parameter [1:0] DDR_TYPE = 2'b00,
	parameter ROM_DATA_WIDTH = 56,
              ROM_OUTPUT_REG 	 = 0,
              ROM_DATA_DEPTH0 	 = 32,
              ROM_DATA_DEPTH1 	 = 32,
              ROM_DATA_DEPTH2 	 = 32,
              ROM_DATA_DEPTH3 	 = 32, 
              ROM_INIT_FILE0  	 = "rom0.hex",
              ROM_INIT_FILE1  	 = "rom1.hex",
              ROM_INIT_FILE2  	 = "rom2.hex",
              ROM_INIT_FILE3  	 = "rom3.hex"
              )
   
    
  (
   //inputs
   input clk,              //System clock 
   input rst_n,            //Active low Reset
   input [3:0] cal_mode,   //cal_mode
   input [1:0] cal_type,
   input restart,          //To reset all the ROM address. 
   input [1:0]sel_reset,   //reset intended ROM address only 
   input [3:0] sel,        //to select which ROM.
   input rd_en,            //to read the data from ROM. 
   //outputs
   output [3:0] rom_rd_full,
   output reg [ROM_DATA_WIDTH-1: 0] ram_data_out //read data from ROM. 2 CLs after read_en. 
   );
   
function integer depth2width;
input [31:0] depth;
// Description:
//   Converts a depth value into a Width.  For instance a depth of
//        a=depth2width(64);
//   sets "a" to 6. 
//  
//   One way to use this is to convert a depth to a width value on a
//   register.  For instance:
//  
//        reg [depth2width(MEM_WIDTH)-1:0] a;
//  
//   
begin : fnDepth2Width
  if (depth > 1) begin
     depth = depth - 1;
     for (depth2width=0; depth>0; depth2width = depth2width + 1)
       depth = depth>>1;
  end
  else
    depth2width = 0;
end
endfunction 

//Internal Signals 
   localparam cROM_DATA_DEPTH = depth2width(ROM_DATA_DEPTH0);
  
   reg [cROM_DATA_DEPTH-1:0] addr0;
   reg [cROM_DATA_DEPTH-1:0] addr1;
   reg [cROM_DATA_DEPTH-1:0] addr2;
   reg [cROM_DATA_DEPTH-1:0] addr3;
   reg [cROM_DATA_DEPTH-1:0] start_addr0;
   reg [cROM_DATA_DEPTH-1:0] start_addr1;
   reg [cROM_DATA_DEPTH-1:0] start_addr2;
   reg [cROM_DATA_DEPTH-1:0] start_addr3;
   wire [ROM_DATA_WIDTH-1:0] data0,data1,data2,data3;
   wire 		     rom0_rd_full,rom1_rd_full,rom2_rd_full,rom3_rd_full;
   wire [1:0] ddr_type;
   wire [3:0] ddr_op;
   
   assign rom_rd_full  = {rom3_rd_full,rom2_rd_full,rom1_rd_full,rom0_rd_full};
   assign rom0_rd_full = (addr0==ROM_DATA_DEPTH0-1);
   assign rom1_rd_full = (addr1==ROM_DATA_DEPTH1-1);
   assign rom2_rd_full = (addr2==ROM_DATA_DEPTH2-1);
   assign rom3_rd_full = (addr3==ROM_DATA_DEPTH3-1);
   assign ddr_type     = DDR_TYPE;
   assign ddr_op       = {ddr_type, cal_type};  
 
   always @(posedge clk)
   begin
	case(cal_mode)
	4'b0001://gl 
	begin
		if(ddr_op == 4'b0010) begin 	//lpddr3_x32_x16
			start_addr0 <= 'hE;
			start_addr1 <= 'h5;
			start_addr2 <= 'h0;
			start_addr3 <= 'h0;
		end
		else if(ddr_op == 4'b0111) begin //ddr3_x32_x16
			start_addr0 <= 'h1A; 
			start_addr1 <= 'h6;  
			start_addr2 <= 'h0;  
			start_addr3 <= 'h0;  
		end
		else if(ddr_op == 4'b1010) begin //lpddr2_x16
			start_addr0 <= 'h0; 
			start_addr1 <= 'h0;
			start_addr2 <= 'h0;  
			start_addr3 <= 'h0;  
		end
		else begin
			start_addr0 <= 'h0;
			start_addr1 <= 'h0;
			start_addr2 <= 'h0;
			start_addr3 <= 'h0;
		end
	end
	4'b0010://wl
	begin
		
			start_addr0 <= 'h0;
			start_addr1 <= 'h0;
			start_addr2 <= 'h0;
			start_addr3 <= 'h0;
	
	end
	4'b0100://rl
	begin
		if(ddr_op == 4'b0010) begin //lpddr3_x16
			start_addr0 <= 'h27; 
			start_addr1 <= 'h12;
			start_addr2 <= 'h0;
			start_addr3 <= 'h0;
		end
		else if(ddr_op == 4'b0111) begin //ddr3_x32_x16
			start_addr0 <= 'h44; 
			start_addr1 <= 'h13;
			start_addr2 <= 'h0;
			start_addr3 <= 'h0;
		end
		else if(ddr_op == 4'b1010) begin //lpddr2_x32_x16
			start_addr0 <= 'h1D;
			start_addr1 <= 'hD;
			start_addr2 <= 'h0;
			start_addr3 <= 'h0;
		end
		else begin
			start_addr0 <= 'h0;
			start_addr1 <= 'h0;
			start_addr2 <= 'h0;
			start_addr3 <= 'h0;
		end
	end
	default:
	begin
		start_addr0 <= 'h0;
		start_addr1 <= 'h0;
		start_addr2 <= 'h0;
		start_addr3 <= 'h0;
	end
	endcase
   end

   always @(posedge clk)
     if (~rst_n || restart || sel_reset[0]) 
       begin
	  addr1 <= start_addr1;
	  addr2 <= start_addr2;
	  addr3 <= start_addr3;
       end
     else if (rd_en)
       begin
	  case(sel[3:1])
	    3'h1: addr1 <= addr1 + 1'b1;
	    3'h2: addr2 <= addr2 + 1'b1;
	    3'h4: addr3 <= addr3 + 1'b1;
	    default : ;
	  endcase // case (sel[3:0])
       end // else: !if(~rst_n)

   always @(posedge clk)
     if (~rst_n || restart || sel_reset[1]) 
       begin
	  addr0 <= start_addr0;
       end
     else if (rd_en)
       begin
	    if(sel[0])
	    	addr0 <= addr0 + 1;
	    else
		addr0 <= addr0;
       end 
   

   always @(posedge clk)
     if (~rst_n)
       ram_data_out <= 'h0;
     else
       case (sel[3:0])
	 4'h1 : ram_data_out <= data0;
	 4'h2 : ram_data_out <= data1;
	 4'h4 : ram_data_out <= data2;
	 4'h8 : ram_data_out <= data3;
	 default : ;
       endcase // case (sel[3:0])
   
   //Every ROM has different size of depth
   //ROM 0
   `IP_MODULE_NAME(single_port_rom) 
     #(.DATA_WIDTH(ROM_DATA_WIDTH),
       .ADDR_WIDTH(depth2width(ROM_DATA_DEPTH0)),
       .OUTPUT_REG(ROM_OUTPUT_REG),
       .RAM_INIT_FILE(ROM_INIT_FILE0))
   u_rom0
     (
      // Outputs
      .data				(data0),
      // Inputs
      .addr				(addr0),
      .clk				(clk));

   //ROM 1
    `IP_MODULE_NAME(single_port_rom) 
     #(.DATA_WIDTH(ROM_DATA_WIDTH),
       .ADDR_WIDTH(depth2width(ROM_DATA_DEPTH1)),
       .OUTPUT_REG(ROM_OUTPUT_REG),
       .RAM_INIT_FILE(ROM_INIT_FILE1))
   u_rom1
     (
      // Outputs
      .data				(data1),
      // Inputs
      .addr				(addr1),
      .clk				(clk));


    `IP_MODULE_NAME(single_port_rom) 
     #(.DATA_WIDTH(ROM_DATA_WIDTH),
       .ADDR_WIDTH(depth2width(ROM_DATA_DEPTH2)),
       .OUTPUT_REG(ROM_OUTPUT_REG),
       .RAM_INIT_FILE(ROM_INIT_FILE2))
   u_rom2
     (
      // Outputs
      .data				(data2),
      // Inputs
      .addr				(addr2),
      .clk				(clk));


    `IP_MODULE_NAME(single_port_rom) 
     #(.DATA_WIDTH(ROM_DATA_WIDTH),
       .ADDR_WIDTH(depth2width(ROM_DATA_DEPTH3)),
       .OUTPUT_REG(ROM_OUTPUT_REG),
       .RAM_INIT_FILE(ROM_INIT_FILE3))
   u_rom3
     (
      // Outputs
      .data				(data3),
      // Inputs
      .addr				(addr3),
      .clk				(clk));


   
endmodule // rom_parser
